function blocked(x,z){return x < -24||x>24||z < -20||z>21||obstacles.some(o=>Math.abs(x-o.x)<o.w&&Math.abs(z-o.z)<o.d)}
function pathTo(x,z){let sx=Math.round(player.position.x),sz=Math.round(player.position.z),ex=Math.round(x),ez=Math.round(z),queue=[[sx,sz]],seen=new Set([sx+','+sz]),prev=new Map(),found=false;for(let qi=0;qi<queue.length&&qi<3000;qi++){let [cx,cz]=queue[qi];if(cx===ex&&cz===ez){found=true;break}for(let [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){let nx=cx+dx,nz=cz+dz,k=nx+','+nz;if(!seen.has(k)&&!blocked(nx,nz)){seen.add(k);prev.set(k,[cx,cz]);queue.push([nx,nz])}}}if(!found)return [];let out=[],cur=[ex,ez];while(cur[0]!==sx||cur[1]!==sz){out.push(new T.Vector3(cur[0],.2,cur[1]));cur=prev.get(cur.join(','));if(!cur)return []}return out.reverse()}
function moveTarget(x,z,action=null){if(blocked(x,z))return toast('Tap open ground beside the building.');pending=null;route=pathTo(x,z);if(!route.length){if(player.position.distanceTo(new T.Vector3(x,.2,z))<1.6){if(action)action();}else toast('No clear route to this item. Try moving closer to its entrance.');return}pending=action;marker.position.set(x,.23,z);marker.visible=true;}
function useStation(st){stationDialog(st)}
function performAt(st,action,label){document.querySelector('dialog').close();activeTask=label;renderTasks();moveTarget(st.approach.x,st.approach.z,()=>{action();activeTask='';renderTasks()});if(!route.length){activeTask='';renderTasks()}else toast(label+' · farmer on the way');}
const touches=new Map();let dragStart=null,gesture=false,multiUsed=false,lastPinch=null;const panOffset=new T.Vector3();
function panPixels(dx,dy){let scale=distance*Math.tan(camera.fov*Math.PI/360)*2/innerHeight;let right=new T.Vector3(Math.cos(angle),0,-Math.sin(angle)),forward=new T.Vector3(Math.sin(angle),0,Math.cos(angle));panOffset.addScaledVector(right,-dx*scale).addScaledVector(forward,-dy*scale/Math.max(.4,elevation));panOffset.x=T.MathUtils.clamp(panOffset.x,-32,32);panOffset.z=T.MathUtils.clamp(panOffset.z,-32,32);}
function pinchData(){let p=[...touches.values()];return {d:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2}}
renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());
renderer.domElement.addEventListener('pointerdown',e=>{touches.set(e.pointerId,{x:e.clientX,y:e.clientY});renderer.domElement.setPointerCapture(e.pointerId);if(touches.size===1){dragStart={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,rotate:e.button===2||e.shiftKey};gesture=false;multiUsed=false;}else {multiUsed=true;gesture=true;lastPinch=pinchData();}});
renderer.domElement.addEventListener('pointermove',e=>{if(!touches.has(e.pointerId))return;touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touches.size>=2){let p=pinchData();if(lastPinch){if(p.d>5)distance=T.MathUtils.clamp(distance*lastPinch.d/p.d,15,70);panPixels(p.x-lastPinch.x,p.y-lastPinch.y)}lastPinch=p;return;}if(!dragStart||multiUsed)return;if(Math.hypot(e.clientX-dragStart.x,e.clientY-dragStart.y)>7)gesture=true;if(gesture){let dx=e.clientX-dragStart.lastX,dy=e.clientY-dragStart.lastY;if(dragStart.rotate){angle-=dx*.006;elevation=T.MathUtils.clamp(elevation+dy*.004,.35,1.4)}else panPixels(dx,dy);}dragStart.lastX=e.clientX;dragStart.lastY=e.clientY;});
function releasePointer(e){if(!touches.has(e.pointerId))return;touches.delete(e.pointerId);if(e.type==='pointercancel'){gesture=true;multiUsed=true;}if(touches.size){lastPinch=null;return;}let tap=!gesture&&!multiUsed&&e.type!=='pointercancel';dragStart=null;lastPinch=null;if(!tap)return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);ray.setFromCamera(pointer,camera);let visible=o=>{for(let p=o;p;p=p.parent)if(!p.visible)return false;return true};let hit=ray.intersectObjects(clickables).find(h=>visible(h.object));if(hit){let st=hit.object.userData.station;if(st){stationDialog(st);return;}let g=hit.object.userData.animal;if(g){inspect(g);return;}}let h=ray.intersectObject(ground)[0];if(h){pending=null;activeTask='Walking';moveTarget(h.point.x,h.point.z);renderTasks();}}
renderer.domElement.addEventListener('pointerup',releasePointer);renderer.domElement.addEventListener('pointercancel',releasePointer);
renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();distance=T.MathUtils.clamp(distance*Math.exp(e.deltaY*.0015),15,70)},{passive:false});
window.addEventListener('keydown',e=>{if(document.querySelector('dialog').open)return;keys[e.key.toLowerCase()]=true;if(e.key.startsWith('Arrow'))e.preventDefault()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{for(const k in keys)keys[k]=false});document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId)});b.addEventListener('pointerup',()=>keys[b.dataset.key]=false);b.addEventListener('pointercancel',()=>keys[b.dataset.key]=false)});
window.zoom=d=>distance=T.MathUtils.clamp(distance+d,20,65);window.home=()=>{angle=.67;distance=innerWidth<700?43:39;panOffset.set(0,0,0);focus.set(0,0,2)};window.rotateCamera=d=>{angle+=d};window.enterStable=()=>{document.querySelector('dialog').close();activeTask='Walking into stable';moveTarget(10,-13,()=>{activeTask='';renderTasks();toast('Inside the stable. Tap a horse, trough or gate.');});};window.toggleStableGate=i=>{let gate=stable.gates[i];if(!gate)return;stable.toggle(gate);document.querySelector('dialog').close();toast(gate.open?'Stall gate opened':'Stall gate closed');};
function modal(html){for(const k in keys)keys[k]=false;document.querySelector('#modalbody').innerHTML=html;let m=document.querySelector('dialog');if(!m.open)m.showModal()}
function run(action,success){try{let r=action();save();updateContents();toast(typeof success==='function'?success(r):success);return true}catch(e){toast(e.message);return false}}
function bag(){return '<div class="bag">'+Object.entries(state.inventory).filter(([k,v])=>v>0).map(([k,v])=>'<span>'+GOODS[k]+': <b>'+v+'</b></span>').join('')+'</div>'}
function roleInfo(){return {livestock:'Livestock keeper',water:'Well owner',grower:'Crop grower',miller:'Feed miller'}[state.role]}
window.openFarmPanel=()=>{modal('<h2>Your farm stores</h2><p>'+roleInfo()+' · Farm day '+state.day+' · All quantities are game units.</p>'+bag()+'<h3>Visit a station</h3><div class="choice"><button onclick="goTo(&quot;well&quot;)">Water well</button><button onclick="goTo(&quot;field&quot;)">Crop field</button><button onclick="goTo(&quot;mill&quot;)">Feed mill</button></div><p>Animals only produce when their paddock has its full daily grain, water and supplement ration.</p><button class="primary" onclick="openRations()">Daily animal requirements</button><p class="note">Specialist farms own one production business. Trade for what you do not make. Nearby buildings can be visited even when not owned.</p><button onclick="chooseRole()">Change playtest role</button>')};
window.goTo=kind=>{document.querySelector('dialog').close();let st=stations.find(s=>s.kind===kind);if(st)useStation(st)};
window.openRations=()=>modal('<h2>Daily paddock rations</h2><p>Production requires every ingredient. A missed ration pauses output; it does not destroy animals. These are balancing values for this game.</p>'+HERDS.map(h=>{let n=demand(h),t=state.troughs[h.id];return '<div class="ration"><b>'+h.name+' · '+h.count+' animals</b>'+Object.entries(n).filter(([k,v])=>v).map(([k,v])=>GOODS[k]+': '+t[k]+'/'+v).join(' · ')+'<br><button onclick="visitTrough(&quot;'+h.id+'&quot;,&quot;feed&quot;)">Visit food bowl</button><button onclick="visitTrough(&quot;'+h.id+'&quot;,&quot;water&quot;)">Visit water trough</button></div>'}).join(''));
window.visitTrough=(id,resource)=>{if(state.role!=='livestock')return toast('This specialist farm has no livestock.');document.querySelector('dialog').close();useStation(stations.find(s=>s.id===id&&s.resource===resource))};
window.fillBowl=(id,kind)=>{let st=stations.find(s=>s.id===id&&s.resource===(kind==='water'?'water':'feed'));let h=HERDS.find(h=>h.id===id),need=Math.max(0,demand(h)[kind]-state.troughs[id][kind]);if(!need)return toast('This ration is already full.');if(state.inventory[kind]<need)return toast('Need '+need+' '+GOODS[kind]+'. Visit the market.');performAt(st,()=>{if(run(()=>fill(state,id,kind),n=>'Added '+n+' '+GOODS[kind]+'.'))triggerCare(id,kind)},'Fill '+h.name+' '+(kind==='water'?'water trough':'food bowl'));};
function stationDialog(st){if(st.kind==='gate'){modal('<h2>Stable stall gate</h2><p>The gate is '+(st.open?'open':'closed')+'. You can walk through the opening when it is open.</p><button class="primary" onclick="toggleStableGate('+stable.gates.indexOf(st)+')">'+(st.open?'Close gate':'Open gate')+'</button>');return;}if(st.kind==='barn'){openFarmPanel();return;}if(st.kind==='stable'){modal('<h2>Walk-in horse stables</h2><p>Two horses live in individual stalls. The front entrance leads into the centre aisle. The roof lifts out of view as you walk inside.</p><div class="choice"><button class="primary" onclick="enterStable()">Enter stable</button><button onclick="visitTrough(&quot;horses&quot;,&quot;feed&quot;)">Feed horses</button><button onclick="visitTrough(&quot;horses&quot;,&quot;water&quot;)">Water horses</button></div><p>Click a stall gate to open or close it. Click a horse to check its care requirements.</p>');return;}if(st.kind==='coop'){modal('<h2>Chicken house</h2><p>Keep grain feed and water in the chicken yard to produce standard and specialty eggs.</p><button class="primary" onclick="visitTrough(&quot;hens&quot;,&quot;feed&quot;)">Chicken care</button>');return;}if(st.kind==='trough'){let h=HERDS.find(h=>h.id===st.id),n=demand(h),t=state.troughs[h.id],food=st.resource==='feed';modal('<h2>'+h.name+' '+(food?'food bowl':'water trough')+'</h2><p>'+h.count+' animals. Daily total: '+Object.entries(n).filter(([k,v])=>v).map(([k,v])=>v+' '+GOODS[k]).join(' + ')+'.</p>'+bag()+'<div class="ration">'+(food?['feed','fruit']:['water']).filter(k=>n[k]>0).map(k=>'<p>'+GOODS[k]+': <b>'+t[k]+'/'+n[k]+'</b> loaded</p><button class="primary" onclick="fillBowl(&quot;'+h.id+'&quot;,&quot;'+k+'&quot;)">Load '+Math.max(0,n[k]-t[k])+' '+GOODS[k]+'</button>').join('')+'</div><p>Choose an action now. Your farmer will walk over and fill the station.</p>');}
else if(st.kind==='well')modal('<h2>Stonewater well</h2><p>Produces <b>40 water / farm day</b>. Pumping consumes 1 power. Water is needed by crops and every animal.</p>'+bag()+'<button class="primary" onclick="produceAt(&quot;well&quot;)">Pump water</button><p>'+(state.role==='water'?'Your well · '+(state.wellReady>state.day?'Refilling until next day':'Ready to collect'):'Not owned. Become a well owner in the playtest, or buy from Willow Wells.')+'</p><button onclick="openMarket()">Water market</button>');
else if(st.kind==='field')modal('<h2>Maize field</h2><p><b>6 water → 24 maize</b>, once per farm day. Growers supply millers.</p>'+bag()+'<button class="primary" onclick="produceAt(&quot;field&quot;)">Water & harvest plot</button><p>'+(state.role==='grower'?'Your crop plot':'Not owned by your current specialist role.')+'</p>');
else modal('<h2>Meadow feed mill</h2><p><b>10 maize + 1 power → 10 grain feed</b>. Millers buy from crop and power suppliers, then sell feed to animal keepers.</p>'+bag()+'<button class="primary" onclick="produceAt(&quot;mill&quot;)">Mill one batch</button><p>'+(state.role==='miller'?'Your feed mill':'Not owned by your current specialist role.')+'</p>')}
window.produceAt=k=>{let st=stations.find(s=>s.kind===k);performAt(st,()=>run(()=>k==='well'?collectWell(state):k==='field'?harvest(state):mill(state),n=>'Produced '+n+' '+(k==='well'?'water':k==='field'?'maize':'grain feed')+'.'),'Work at '+(k==='well'?'the water well':k==='field'?'the maize field':'the feed mill'));};
window.nextDay=()=>{let r=advance(state);save();updateContents();toast('Day '+state.day+'. '+r.produced.length+' paddocks produced.'+(r.skipped.length?' '+r.skipped.length+' paused: missing rations.':''));};
window.openMarket=()=>modal('<h2>Meadow exchange</h2><p class="note">SIMULATED SUPPLIERS & BUYERS · Not live users. Finite stock and demand. All trades use non-withdrawable farm coins. Sell fee: 5%, rounded up to one coin.</p>'+bag()+'<p>Quantity <select onchange="marketQty(this.value)"><option value="1" '+(marketQuantity===1?'selected':'')+'>1</option><option value="5" '+(marketQuantity===5?'selected':'')+'>5</option><option value="10" '+(marketQuantity===10?'selected':'')+'>10</option><option value="25" '+(marketQuantity===25?'selected':'')+'>25</option></select></p><table><tr><th>Goods / partner</th><th>Price</th><th>Stock / demand</th><th>Trade</th></tr>'+state.offers.map(o=>'<tr><td>'+GOODS[o.good]+'<br><small>'+o.seller+'</small></td><td>'+o.price+' ◉</td><td>'+o.stock+' / '+o.buy+'</td><td>'+(o.stock>0?'<button onclick="makeTrade(&quot;'+o.good+'&quot;,&quot;buy&quot;)">Buy '+marketQuantity+'</button>':'')+(o.buy>0?'<button onclick="makeTrade(&quot;'+o.good+'&quot;,&quot;sell&quot;)">Sell '+marketQuantity+'</button>':'')+'</td></tr>').join('')+'</table><p>Partner orders do not refill when you advance a day. Real shared listings and accounts are not connected yet.</p>');
window.marketQty=v=>{marketQuantity=Number(v);window.openMarket()};window.makeTrade=(k,side)=>{if(run(()=>trade(state,k,marketQuantity,side),r=>side==='buy'?'Bought '+marketQuantity+' '+GOODS[k]+'.':'Sold '+marketQuantity+' '+GOODS[k]+'. Net '+(r.gross-r.fee)+' coins.'))window.openMarket()};
window.openCycle=()=>modal('<h2>A connected farm economy</h2><div class="steps"><span>Power supplier</span><span>↓ Well → Water</span><span>↓ Grower → Maize</span><span>↓ Miller → Grain feed</span><span>↓ Animal keeper → Produce</span><span>↓ Buyers / processing</span></div><p>Fruit-feed suppliers provide daily supplements. Animals supply fertiliser to growers; specialist chicken breeds produce different eggs, pigs produce truffles and fertiliser, cows produce milk, horses gain condition for future racing.</p><p class="note">This build tests resource dependencies, not cash profitability. Real user trading, processing demand and cash-funded contracts still need a shared server economy.</p><button onclick="chooseRole()">Try a specialist farm</button>');
window.chooseRole=()=>modal('<h2>Choose a playtest farm</h2><p>Each role owns one productive business. Changing role keeps your inventory and trade history, clears unconsumed trough contents back into storage, and changes visible active animals.</p><div class="choice">'+[['livestock','Livestock keeper'],['water','Well owner'],['grower','Crop grower'],['miller','Feed miller']].map(([k,v])=>'<button onclick="setRole(&quot;'+k+'&quot;)">'+v+'</button>').join('')+'</div>');
window.setRole=r=>{if(!['livestock','water','grower','miller'].includes(r))return;for(const t of Object.values(state.troughs))for(const k of ['feed','water','fruit']){state.inventory[k]+=t[k];t[k]=0}state.role=r;save();updateContents();document.querySelector('dialog').close();toast(roleInfo()+'. Trade for missing resources.');};
window.showAvatar=()=>modal('<h2>Your farmer</h2><div class="choice"><button onclick="chooseAvatar(&quot;man&quot;)">Male farmer</button><button onclick="chooseAvatar(&quot;lady&quot;)">Female farmer</button></div><p>Tap ground to walk. Tap bowls, the well, mill or crops to walk over and interact. Drag to rotate; use + / − to zoom.</p>');window.chooseAvatar=a=>{state.avatar=a;save();avatar();document.querySelector('dialog').close()};
function inspect(g){let h=HERDS.find(h=>h.id===g.userData.herd),n=demand(h);modal('<h2>'+g.userData.name+'</h2><p>Per-animal daily ration: '+Object.entries(RATIONS[h.type]).filter(([k,v])=>v).map(([k,v])=>v+' '+GOODS[k]).join(' + ')+'.</p><p>Paddock output with full rations: '+Object.entries(h.goods).map(([k,v])=>v+' '+GOODS[k]).join(', ')+'.</p><button onclick="visitTrough(&quot;'+h.id+'&quot;,&quot;feed&quot;)">Visit food bowl</button><button onclick="visitTrough(&quot;'+h.id+'&quot;,&quot;water&quot;)">Visit water trough</button>')}
function updateContents(){for(const st of stations)if(st.kind==='trough'){let t=state.troughs[st.id];st.contents.visible=state.role==='livestock'&&(st.resource==='water'?t.water>0:t.feed+t.fruit>0)}for(const a of animals)a.g.visible=state.role==='livestock';}updateContents();
function triggerCare(id,kind){let st=stations.find(s=>s.id===id&&s.resource===(kind==='water'?'water':'feed'));animals.filter(a=>a.g.userData.herd===id).forEach((a,i)=>{a.dest.set(a.type==='horse'?a.x:st.x+(i-1)*.8,.2,a.type==='horse'?-11.5:st.z-1.1);a.wait=0;a.behavior='approaching';a.eatKind=kind;});}
function animate(){requestAnimationFrame(animate);let dt=Math.min(clock.getDelta(),.04),time=clock.elapsedTime;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dz=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(dx||dz){let v=new T.Vector3(dx,0,dz).normalize().applyAxisAngle(new T.Vector3(0,1,0),angle);route=[player.position.clone().addScaledVector(v,1)];pending=null;marker.visible=false;}let actual=0;if(route.length&&!document.querySelector('dialog').open){let dest=route[0],v=dest.clone().sub(player.position);v.y=0;let len=v.length(),step=Math.min(len,dt*2.7);if(len>.02){v.normalize();let nx=player.position.x+v.x*step,nz=player.position.z+v.z*step;if(!blocked(nx,nz)){player.position.x=nx;player.position.z=nz;actual=step;let wanted=Math.atan2(v.x,v.z),diff=Math.atan2(Math.sin(wanted-player.rotation.y),Math.cos(wanted-player.rotation.y));player.rotation.y+=diff*Math.min(1,dt*12);}else {route=[];pending=null;}}if(len<.12)route.shift();}if(actual>0){playerPhase+=actual*8;limbs.forEach(l=>{let sign=l.userData.side*(l.userData.kind==='arm'?-1:1);l.rotation.x=Math.sin(playerPhase)*.58*sign;});player.position.y=.2+Math.abs(Math.sin(playerPhase))*.025;}else{limbs.forEach(l=>l.rotation.x*=Math.max(0,1-dt*12));player.position.y=.2;}if(!route.length){marker.visible=false;if(activeTask==='Walking'){activeTask='';renderTasks();}if(pending&&!document.querySelector('dialog').open){let f=pending;pending=null;f();}}shadow.position.set(player.position.x,.21,player.position.z);
stable.update(player.position);for(const a of animals){if(!a.g.visible)continue;let v=a.dest.clone().sub(a.g.position);v.y=0;let len=v.length(),moved=0;if(len>.06){let step=Math.min(len,dt*.55);v.normalize();a.g.position.addScaledVector(v,step);let wanted=Math.atan2(v.x,v.z),diff=Math.atan2(Math.sin(wanted-a.g.rotation.y),Math.cos(wanted-a.g.rotation.y));a.g.rotation.y+=diff*Math.min(1,dt*5);moved=step;a.walkPhase+=step*10;}else if(a.behavior==='approaching'){a.behavior='eating';a.wait=5;a.g.rotation.y=0;}else {a.wait-=dt;if(a.wait<=0){a.behavior='idle';a.wait=3+Math.random()*5;a.dest.set(a.x+(Math.random()-.5)*(a.type==='horse'?.5:1.8),.2,a.z+(Math.random()-.5)*(a.type==='horse'?1.1:1.6));}}if(a.mixer){setAnimalMotion(a,a.behavior==='eating'?'eat':moved?'walk':'idle',moved/dt);a.mixer.update(dt);animateRigDetails(a,dt);}else a.legs.forEach((l,i)=>{let p=l.userData.phase??(i%2?0:Math.PI);l.rotation.x=moved?Math.sin(a.walkPhase+p)*.42:l.rotation.x*Math.max(0,1-dt*12)});a.g.position.y=.2+(a.behavior==='eating'?Math.sin(time*4)*.018:0);}sail.rotation.z+=dt*.2;let desired=new T.Vector3(player.position.x*.35,0,player.position.z*.35+1).add(panOffset);focus.lerp(desired,1-Math.exp(-dt*1.8));camera.position.set(focus.x+Math.sin(angle)*distance,distance*elevation,focus.z+Math.cos(angle)*distance);camera.lookAt(focus);renderer.render(scene,camera);}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});document.querySelector('#loading').remove();renderTasks();animate();upgradeAnimals(animals,(type,ok)=>{if(ok){for(const a of animals.filter(a=>a.type===type))a.model?.traverse(o=>{if(o.isMesh)clickables.push(o)});}if(ok)toast((type==='horse'?'Rigged horses':type==='cow'?'Rigged cows':'Rigged pigs')+' loaded with movement animations.');});

function iconSvg(kind){const art={water:'<path d="M40 10C28 28 17 40 17 53a23 23 0 0 0 46 0c0-13-11-25-23-43Z" fill="#79b8ca"/><path d="M27 50q-3 14 12 15" stroke="#d9f3f4" stroke-width="5" fill="none" stroke-linecap="round"/>',feed:'<path d="M25 25h30l9 39q-24 12-48 0Z" fill="#c7a16b"/><path d="M23 25h34l-5-10H28Z" fill="#e1c58a"/><path d="M40 36v28m0-20-9-6m9 13 10-7m-10 15-9-7" stroke="#fff0c0" stroke-width="3"/>',maize:'<ellipse cx="42" cy="40" rx="13" ry="26" fill="#e4bf62"/><path d="M40 68Q12 55 20 31q20 12 20 37M42 68Q67 54 64 34Q44 45 42 68" fill="#80a36a"/><path d="M38 20v35m8-35v35" stroke="#f5d988" stroke-width="2"/>',mill:'<path d="M27 70l5-41h20l6 41Z" fill="#c2a57d"/><path d="M42 13v48M18 37h48" stroke="#665a45" stroke-width="4"/><path d="M34 8h14v22H34Zm17 22h22v14H51ZM36 45h14v24H36ZM9 30h23v14H9Z" fill="#ece2bd"/>',check:'<circle cx="40" cy="40" r="28" fill="#9bb787"/><path d="m25 40 10 10 21-23" stroke="#fff8dc" stroke-width="6" fill="none" stroke-linecap="round"/>'};return '<svg viewBox="0 0 80 80" aria-hidden="true">'+(art[kind]||art.check)+'</svg>';}
function renderTasks(){let root=document.querySelector('#task-content');if(!root)return;let done=HERDS.filter(h=>Object.entries(demand(h)).every(([k,v])=>state.troughs[h.id][k]>=v)).length;document.querySelector('#task-count').textContent=state.role==='livestock'?done+'/4 ready':roleInfo();let html='<div class="task-intro"><b>'+roleInfo()+'</b><span>Day '+state.day+' · '+(activeTask||'Choose your next task')+'</span></div>';if(state.role==='livestock'){html+=HERDS.map(h=>{let n=demand(h),t=state.troughs[h.id],food=t.feed>=n.feed&&t.fruit>=n.fruit,water=t.water>=n.water;return '<article class="task-card"><div class="task-title"><span class="species">'+({cow:'🐄',pig:'🐖',chicken:'🐔',horse:'🐎'}[h.type])+'</span><div><b>'+h.name+'</b><small>'+h.count+' animals · '+(food&&water?'Ready to produce':'Needs daily care')+'</small></div></div><div class="task-pair"><button onclick="visitTrough(&quot;'+h.id+'&quot;,&quot;feed&quot;)">'+iconSvg('feed')+'<b>Food bowl</b><small>'+t.feed+'/'+n.feed+' grain'+(n.fruit?' · '+t.fruit+'/'+n.fruit+' fruit':'')+'</small><em>'+(food?'✓ Filled':'Fill bowl →')+'</em></button><button onclick="visitTrough(&quot;'+h.id+'&quot;,&quot;water&quot;)">'+iconSvg('water')+'<b>Water trough</b><small>'+t.water+'/'+n.water+' water</small><em>'+(water?'✓ Filled':'Add water →')+'</em></button></div></article>'}).join('');html+='<button class="task-next" onclick="nextDay()">☀ Finish farm day · '+done+'/4 paddocks ready</button>';}else {let k=state.role==='water'?'well':state.role==='grower'?'field':'mill';html+='<article class="task-card"><div class="task-art">'+iconSvg(state.role==='water'?'water':state.role==='grower'?'maize':'mill')+'</div><h3>'+({water:'Pump & sell water',grower:'Grow maize',miller:'Make animal feed'}[state.role])+'</h3><p>'+({water:'1 power → 40 water, once a day.',grower:'6 water → 24 maize, once a day.',miller:'10 maize + 1 power → 10 grain feed.'}[state.role])+'</p><button class="task-next" onclick="goTo(&quot;'+k+'&quot;)">Choose production action →</button></article>';}html+='<button class="task-market" onclick="openMarket()">🧺 Missing supplies? Open market</button><p class="task-tip">Tap an item to see actions immediately. Your farmer walks over after you choose.</p>';root.innerHTML=html;}
window.toggleTasks=()=>{document.querySelector('#tasks').classList.toggle('expanded')};
